Name the single transformation that moves $\triangle ABC$ onto $\triangle DEF$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0,0);
\coordinate (B) at (2.4,0.4);
\coordinate (C) at (0.9,1.6);
\coordinate (D) at (3.4,0.6);
\coordinate (E) at (5.8,1.0);
\coordinate (F) at (4.3,2.2);
\draw (A) -- (B) -- (C) -- cycle;
\draw (D) -- (E) -- (F) -- cycle;
\node[below left] at (A) {$A$};
\node[below right] at (B) {$B$};
\node[above] at (C) {$C$};
\node[below left] at (D) {$D$};
\node[below right] at (E) {$E$};
\node[above] at (F) {$F$};
\end{tikzpicture}
[/tikz]

